use glam::DVec3 as V;use ingetrazo_core::{image_plane::ImagePlane,groups::Group,scene::SelectionItem,math::Ray};use ingetrazo_gui::IngeTrazoApp;use ingetrazo_tools::base::{ToolContext,ToolType};
fn ctx(p:V)->ToolContext{ToolContext::new(p,Ray::new(V::new(0.5,0.5,10.),-V::Z))}fn geometry(a:&IngeTrazoApp)->Vec<[f64;3]>{let mut points=a.scene.mesh.vertices.iter().map(|v|v.position.to_array()).collect::<Vec<_>>();fn walk(g:&Group,parent:glam::DMat4,p:&mut Vec<[f64;3]>){let world=parent*g.transform;p.extend(g.mesh.vertices.iter().map(|v|world.transform_point3(v.position).to_array()));for child in &g.children{walk(child,world,p);}}for g in &a.scene.groups{walk(g,glam::DMat4::IDENTITY,&mut points);}points.sort_by(|a,b|a[0].total_cmp(&b[0]).then(a[1].total_cmp(&b[1])).then(a[2].total_cmp(&b[2])));points}
fn state(a:&IngeTrazoApp)->serde_json::Value{serde_json::json!({"origin":a.scene.image_planes[0].origin,"active":a.active_tool_type==ToolType::Move&&a.active_tool.snap_anchor().is_some(),"editing":!a.component_edit_stack.is_empty(),"undo":a.undo_stack.len(),"geometry":geometry(a)})}
fn main(){let mut rows=serde_json::Map::new();for context_kind in ["plain","component","folded","nested","nested_folded"]{for case in ["finish_live","cancel_then_finish"]{let mut a=IngeTrazoApp::new();a.system_clipboard=None;let mut group=Group::new("Leaf");group.mesh.add_vertex(V::ZERO);group.mesh.add_vertex(V::X);group.mesh.add_vertex(V::Y);group.mesh.add_face(vec![0,1,2],vec![]);let leaf=group.id;if context_kind.starts_with("nested"){let mut outer=Group::new("Outer");outer.children.push(group);a.scene.groups.push(outer);let id=a.scene.groups[0].id;a.scene.make_component(id).unwrap();}else{a.scene.groups.push(group);if context_kind!="plain"{a.scene.make_component(leaf).unwrap();}}a.scene.image_planes.push(ImagePlane::new("scan",V::new(0.125,-1.25,2.5),V::X*2.,V::Y*2.));a.scene.select(SelectionItem::Group(0));a.begin_component_edit();if context_kind.starts_with("nested"){a.scene.clear_selection();a.scene.select(SelectionItem::Group(0));a.begin_component_edit();}if ["folded","nested_folded"].contains(&context_kind){a.save_undo_state();a.scene.mesh.vertices[0].position+=V::Z*0.25;a.scene.bump_version();}a.scene.clear_selection();a.scene.select(SelectionItem::ImagePlane(0));a.scene.select(SelectionItem::Face(0));a.set_tool(ToolType::Move);let mut states=vec![state(&a)];a.dispatch_tool_click(&ctx(V::ZERO));a.dispatch_tool_move(&ctx(V::new(1.,2.,0.)));a.dispatch_tool_move(&ctx(V::new(2.,3.,0.)));states.push(state(&a));if case=="cancel_then_finish"{a.active_tool.on_cancel(&mut a.scene);states.push(state(&a));}while !a.component_edit_stack.is_empty(){a.finish_component_edit();}states.push(state(&a));if case=="finish_live"{a.dispatch_tool_move(&ctx(V::new(3.,4.,0.)));states.push(state(&a));a.dispatch_tool_click(&ctx(V::new(5.,2.,0.)));states.push(state(&a));a.undo();states.push(state(&a));a.redo();states.push(state(&a));}a.active_tool.on_cancel(&mut a.scene);states.push(state(&a));rows.insert(format!("{context_kind}:{case}"),serde_json::json!(states));}}println!("{}",serde_json::to_string_pretty(&rows).unwrap());}
